/**
 * Permanent end-to-end verify for Word / Excel / CSV reading. Run: npm run verify:office-files  (about a few minutes, 1 CPU)
 *
 * What it does, per fixture in scripts/office-fixtures (generated by gen.mjs, answers in expected.json written BEFORE any run):
 *   a) upload gate: checkUploadFile (api/_lib/uploadTypes.js) AND the real createUploadUrl path accept/reject as expected
 *   b) read: the real ingestDocument on PGlite (RLS role) with R2 mocked by a patched fetch and a model stub that fails the run
 *      if called; every non-R2 request (XXE / SSRF / external links) is recorded and fails the run
 *   c) status: read vs refused-with-reason-class (plain message with a "what to do"), nothing stored for a refusal
 *   d) TEXT RECALL: share of expected key strings / cell values present in the stored page text (per file and per type)
 *   e) QUESTIONS: for each expected question the app's own page search (db.searchPassages, the same function Donovan's
 *      search_documents evidence step uses; keyword/full-text only, PGlite has no pgvector) is run scoped to that document.
 *      PASS = the TOP result's page contains every expected answer string (any-of variants) plus the co-located row/entity
 *      strings, none of the must-not strings, the sheet name for workbooks, and (Word/text) the page number is within tolerance.
 *      Also reported: answer present anywhere in the top 5 ("top-k").
 *      NOTE: where a question needs the live model to compose the sentence, or to COUNT, this measures retrieval-with-right-
 *      source only (aggregates check that every sampled matching row is present in the stored text).
 *   f) company isolation: everything is ingested as tenant A; tenant B searching finds nothing, scoped or not
 *   g) per-type table; exits non-zero on any miss
 * Independence: this harness never looks at the readers' source, only at what is stored.
 */
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

for (const k of ['STRIPE_SECRET_KEY', 'CLERK_SECRET_KEY', 'RESEND_API_KEY', 'ANTHROPIC_API_KEY']) delete process.env[k];
process.env.NEON_CONNECTION_STRING = 'postgres://fixture_user:fixture_pw@db.fixture.invalid:5432/fixture?sslmode=require&channel_binding=require';
Object.assign(process.env, { R2_ACCOUNT_ID: 'acct123', R2_ACCESS_KEY_ID: 'AKIAFIXTURE', R2_SECRET_ACCESS_KEY: 'secretfixture', R2_BUCKET_NAME: 'fixture-bucket' });

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const rel = (p) => path.join(root, p);
const FIX = rel('scripts/office-fixtures');
const ONLY = process.argv.find((a) => a.startsWith('--only='))?.slice(7);
const VERBOSE = process.argv.includes('--verbose');
const PROBE_ID = process.argv.includes('--probe-id'); // diagnostic only: search by the bare identifier instead of the question

/* ---------------------------------------------------------------- (a) run the generator, which also proves the oracle is untouched */
{
  const g = spawnSync(process.execPath, [path.join(FIX, 'gen.mjs')], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  process.stdout.write(g.stdout ?? '');
  if (g.status !== 0) { console.error(g.stderr || 'generator failed'); process.exit(1); }
}
const EXPECTED = JSON.parse(fs.readFileSync(path.join(FIX, 'expected.json'), 'utf8'));
const errataDir = path.join(FIX, 'errata'); // dated errata files (never edits to expected.json) are listed so reviewers see them
const errata = fs.existsSync(errataDir) ? fs.readdirSync(errataDir) : [];
if (errata.length) console.log(`errata on file: ${errata.join(', ')}`);
// Errata never edit expected.json: each errata/*.json is [{file, set: {'structure.pagesRange': [..]} | question: {index, set:{pageTolerance}}, why}] applied in memory.
for (const f of errata.filter((x) => x.endsWith('.json'))) {
  for (const e of JSON.parse(fs.readFileSync(path.join(errataDir, f), 'utf8'))) {
    const t = EXPECTED.files[e.file]; if (!t) continue;
    if (e.question != null) Object.assign(t.questions.find((x) => x.question.startsWith(e.question)) ?? {}, e.set);
    else for (const [k, v] of Object.entries(e.set)) { const ks = k.split('.'); let o = t; for (const kk of ks.slice(0, -1)) o = o[kk]; o[ks.at(-1)] = v; }
  }
}

/* ---------------------------------------------------------------- bookkeeping */
const failures = [];
// errata/known-limits.json: [{file, question (prefix), reason, date}]. A listed miss prints as KNOWN LIMIT, is counted apart and never as a pass.
const KL_PATH = path.join(FIX, 'errata', 'known-limits.json');
const KNOWN = fs.existsSync(KL_PATH) ? JSON.parse(fs.readFileSync(KL_PATH, 'utf8')) : [];
const knownHit = (file, question) => KNOWN.find((k) => k.file === file && question.startsWith(k.question));
let knownLimitCount = 0; const klSeen = new Set();
const fail = (file, what) => { failures.push(`${file}: ${what}`); console.log(`FAIL  ${file}: ${what}`); };
const typeStats = {}; // ext -> {files, statusOk, keys, keysHit, qTotal, qTop1, qTopK, aggTotal, aggOk, refusedOk, refusedTotal}
const ts = (e) => (typeStats[e] ??= { files: 0, statusOk: 0, keys: 0, keysHit: 0, qTotal: 0, qTop1: 0, qTopK: 0, aggTotal: 0, aggOk: 0 });

/* ---------------------------------------------------------------- PGlite harness (same pattern as verify-r34-breakit-uploads) */
const { PGlite } = await import('@electric-sql/pglite');
const contrib = {};
for (const key of ['uuid_ossp', 'pgcrypto', 'pg_trgm', 'btree_gin']) contrib[key] = (await import(`@electric-sql/pglite/contrib/${key}`))[key];
const lite = new PGlite({ extensions: contrib });
const cfgDir = rel('M3-config');
for (const f of fs.readdirSync(cfgDir).filter((x) => /^\d\d.*\.sql$/.test(x) && !x.startsWith('99')).sort()) {
  try { await lite.exec(fs.readFileSync(path.join(cfgDir, f), 'utf8')); } catch { /* optional migrations */ }
}
try { await lite.exec(fs.readFileSync(path.join(cfgDir, '01b-app-role.sql'), 'utf8')); } catch { /* optional */ }
const pgMod = (await import('pg')).default;
{
  let tail = Promise.resolve();
  const lock = () => { let release; const p = new Promise((r) => { release = r; }); const prev = tail; tail = tail.then(() => p); return prev.then(() => release); };
  pgMod.Pool.prototype.connect = async function connect() {
    const release = await lock();
    await lite.exec('SET ROLE deepwell_rls');
    return { query: (sql, params) => lite.query(sql, params), release: () => { lite.exec('RESET ROLE').finally(release); } };
  };
  pgMod.Pool.prototype.query = async function query(sql, params) {
    const release = await lock();
    try { return await lite.query(sql, params); } finally { release(); }
  };
}
const RS = await import(rel('api/_lib/recordsStore.js'));
const PLAN = await import(rel('api/_lib/plan.js'));
const UP = await import(rel('api/upload-url.js'));
const RD = await import(rel('api/_lib/readDocument.js'));
let UT = null;
try { UT = await import(rel('api/_lib/uploadTypes.js')); } catch (e) { fail('(setup)', `api/_lib/uploadTypes.js did not load: ${e.message}`); }
if (UT && typeof UT.checkUploadFile !== 'function') { fail('(setup)', 'api/_lib/uploadTypes.js does not export checkUploadFile (engineer B has not delivered it yet)'); }
const rnd = () => crypto.randomBytes(32).toString('hex');
const newTenant = async (key) => {
  const ctx = await RS.getTenantContext(key, key);
  await lite.query(`UPDATE tenants SET billing_status='active', plan='fleet' WHERE id = $1`, [ctx.id]);
  RS._resetTenantContextCache?.(); PLAN._resetBillingRowCache?.();
  return ctx.id;
};
await newTenant('org_office_a');
await newTenant('org_office_b');
const authA = { userId: 'user_a', tenantId: 'org_office_a', orgId: 'org_office_a', orgRole: 'admin' };
const ctxA = { tenantKey: 'org_office_a', tenantName: 'org_office_a' };
const ctxB = { tenantKey: 'org_office_b', tenantName: 'org_office_b' };

/* mock R2 + egress watch: only the fixture bucket may be contacted */
const store = new Map();
const outbound = [];
const realFetch = globalThis.fetch;
globalThis.fetch = async (url, init = {}) => {
  const u = new URL(String(url));
  if (!/\.r2\.cloudflarestorage\.com$/.test(u.hostname) && !u.hostname.includes('fixture')) { outbound.push(String(url)); return new Response('blocked by harness', { status: 599 }); }
  const key = decodeURIComponent(u.pathname.replace(/^\/[^/]+\//, ''));
  if ((init.method ?? 'GET') === 'DELETE') { store.delete(key); return new Response(null, { status: 204 }); }
  const b = store.get(key);
  if (!b) return new Response('nope', { status: 404 });
  return new Response(b, { status: 200, headers: { 'content-length': String(b.length) } });
};
let modelCalls = 0;
RD.__setAnthropicClientFactoryForTests(() => ({ messages: { create: async () => { modelCalls++; throw new Error('model must not be called for office/text files'); } } }));

/* ---------------------------------------------------------------- helpers */
const CLASS_RE = {
  empty: /empty|no (readable )?(text|content|data)|nothing (to read|in)|blank|0 bytes/i,
  corrupt: /corrupt|damaged|truncated|incomplete|could not be (opened|read)|couldn.t be (opened|read)|can.?t be (opened|read)|not a valid|isn.t a valid|unreadable|broken|malformed|re-?(save|export)/i,
  mismatch: /is named|really (a|an)|doesn.?t match|does not match|not match|isn.?t (really|actually|a (real|valid))|is not a (real|valid)|renamed|actually (a|an)|looks like|file type|extension|not a (pdf|word|excel|docx|xlsx|photo|jpeg|png)|different (type|kind|format)|program|web page|image/i,
  encrypted: /password|encrypt|protected/i,
  legacy: /older|legacy|\.doc\b|\.xls\b|\.ppt\b|97|2003|save as|convert|binary/i,
  macro: /macro|vba|\.xlsm|\.docm|\.dotm/i,
  limit: /too (large|big|many|deep|complex|much)|limit|exceed|maximum|larger than|bomb|safety|expands|more than|far more|internal parts/i,
  hostile: /unsafe|not safe|security|blocked|suspicious|malicious|can.?t (be )?(read|open)|couldn.?t|not (supported|accepted)|refus|too|corrupt|invalid/i,
  unsupported: /not (supported|accepted|allowed)|unsupported|can.?t accept|only accept|isn.?t accepted|accepted types|we accept|heic|heif|convert|zip|program|program or/i,
};
const ACTION_RE = /\b(save|export|convert|re-?upload|upload|send|remove|try|open|use|take|split|unlock|re-?save|share|choose|pick|check|photo|copy)\b/i;
const PLAIN_BAD = /undefined|\[object|\bat .*\.(js|ts):\d+|ERR_[A-Z_]+|node:|stack|TypeError|RangeError|ENOENT|JSZip|fflate|\/home\/claude/;
const norm = (s) => String(s).toLowerCase().replace(/\s+/g, ' ');
const has = (hay, alt) => (Array.isArray(alt) ? alt : [alt]).some((a) => norm(hay).includes(norm(a)));
const rowsOf = async (docId) => (await lite.query('select * from document_pages where document_id = $1 order by page_no', [docId])).rows;
const hayOfPage = (row) => Object.entries(row).filter(([k]) => !/^(tsv|embedding|id|tenant_id|document_id|created_at|updated_at)$/.test(k) && !/embed|vector/.test(k)).map(([, v]) => (typeof v === 'string' ? v : v == null || typeof v === 'number' ? (typeof v === 'number' ? '' : '') : JSON.stringify(v))).join('\n');
const pct = (a, b) => (b ? `${((100 * a) / b).toFixed(1)}%` : 'n/a');
const callCheck = async (meta, name, size) => {
  if (!UT || typeof UT.checkUploadFile !== 'function') return { ok: null };
  try {
    const r = await UT.checkUploadFile({ filename: name, name, contentType: meta.contentType, type: meta.contentType, sizeBytes: size, size, bytes: undefined });
    if (r === false) return { ok: false };
    if (r && typeof r === 'object' && (r.ok === false || r.error || r.reject || r.accepted === false)) return { ok: false, msg: r.message ?? r.error };
    return { ok: true };
  } catch (e) { return { ok: false, msg: e.message }; }
};

/* ---------------------------------------------------------------- main loop */
const names = Object.keys(EXPECTED.files).sort().filter((n) => !ONLY || n.includes(ONLY));
const t0 = Date.now();
const ingested = []; // {name, docId, pages}
const perFile = [];
for (const name of names) {
  const exp = EXPECTED.files[name];
  const bytes = fs.readFileSync(path.join(FIX, 'files', name));
  const st = ts(exp.type); st.files++;
  const tf = Date.now();
  let okStatus = true;
  const bad = (m) => { okStatus = false; fail(name, m); };

  // (a) upload gate
  const chk = await callCheck(exp, name, bytes.length);
  if (chk.ok === null) bad('checkUploadFile unavailable');
  else if ((exp.upload === 'accept') !== chk.ok && bytes.length > 0) bad(`checkUploadFile ${chk.ok ? 'accepted' : 'rejected'} but expected ${exp.upload}`);
  const sha = rnd();
  let created = null; let uploadErr = null;
  const before = (await lite.query('select count(*)::int n from documents')).rows[0].n;
  try { created = await UP.createUploadUrl(authA, { filename: name, sha256: sha, contentType: exp.contentType, sizeBytes: Math.max(0, bytes.length) }); } catch (e) { uploadErr = e; }
  const after = (await lite.query('select count(*)::int n from documents')).rows[0].n;
  if (exp.upload === 'reject') {
    if (!uploadErr) bad('createUploadUrl accepted a file that must be refused at upload');
    else {
      if (!(uploadErr.status >= 400 && uploadErr.status < 500)) bad(`upload refusal was status ${uploadErr.status}, want 4xx`);
      if (after !== before) bad('a refused upload still created a document row');
      if (PLAIN_BAD.test(uploadErr.message ?? '')) bad(`upload refusal message not plain: ${uploadErr.message}`);
      if (!ACTION_RE.test(uploadErr.message ?? '') && !/accept|support/i.test(uploadErr.message ?? '')) bad(`upload refusal has no what-to-do: ${uploadErr.message}`);
    }
    if (okStatus) st.statusOk++;
    perFile.push({ name, type: exp.type, stage: 'upload-refused', ok: okStatus, ms: Date.now() - tf });
    continue;
  }
  if (uploadErr) { bad(`upload of an acceptable file failed: ${uploadErr.status} ${uploadErr.message}`); perFile.push({ name, type: exp.type, ok: false }); continue; }

  if (exp.status === 'model-path') {
    const sn = RD.sniffMagicBytes(bytes);
    const want = exp.type === 'png' ? 'image/png' : 'image/jpeg';
    if (sn !== want) bad(`sniff ${sn}, want ${want}`);
    if (okStatus) st.statusOk++;
    perFile.push({ name, type: exp.type, stage: 'model-path (upload+sniff only)', ok: okStatus, ms: Date.now() - tf });
    continue;
  }

  // (b) the real read
  const [{ storage_key }] = (await lite.query('select storage_key from documents where id=$1', [created.documentId])).rows;
  store.set(storage_key, bytes);
  const outBefore = outbound.length; const mBefore = modelCalls;
  let res = null; let err = null; const tr = Date.now();
  try { res = await RD.ingestDocument(ctxA, created.documentId, { userId: 'user_a' }); } catch (e) { err = e; }
  const elapsed = Date.now() - tr;
  if (elapsed > 30_000) bad(`read took ${elapsed} ms (wall limit is 20 s)`);
  if (outbound.length > outBefore) bad(`made non-R2 network requests: ${outbound.slice(outBefore).join(', ')}`);
  if (modelCalls > mBefore) bad('the model was called for a file that must be read for free');
  const pages = await rowsOf(created.documentId);
  const hay = pages.map(hayOfPage);
  const allText = hay.join('\n');

  const readOk = !err && !!res;
  if (exp.status === 'read' && !readOk) bad(`expected read, got refusal: ${err?.status} ${err?.message}`);
  if (exp.status === 'refused' && readOk) bad(`expected refusal (${exp.reason.join('/')}), but it was read (${pages.length} pages)`);
  if (exp.status !== 'read' && err) {
    const msg = String(err.message ?? '');
    if (!exp.reason.some((c) => CLASS_RE[c]?.test(msg))) bad(`refusal message does not match class ${exp.reason.join('/')}: "${msg}"`);
    if (PLAIN_BAD.test(msg) || msg.length < 12) bad(`refusal message not plain: "${msg}"`);
    if (!ACTION_RE.test(msg)) bad(`refusal message gives no what-to-do: "${msg}"`);
    if (!(err.status >= 400 && err.status < 500)) bad(`refusal status ${err.status}, want 4xx`);
    if (pages.length) bad(`refused file still stored ${pages.length} pages`);
  }
  if (exp.neverWritePaths && fs.existsSync('/home/claude/work/evil.txt')) bad('traversal entry was written to disk');
  if (exp.mustNotAnywhere) for (const m of exp.mustNotAnywhere) if (allText.includes(m)) bad(`stored text contains forbidden "${m}"`);

  if (readOk && (exp.status === 'read' || exp.status === 'either')) {
    // structure
    const s = exp.structure ?? {};
    const n = pages.length;
    if (n === 0 && exp.status === 'read') bad('read ok but zero pages stored');
    if (s.pagesRange && (n < s.pagesRange[0] || n > s.pagesRange[1])) bad(`page count ${n} outside expected ${s.pagesRange[0]}..${s.pagesRange[1]}`);
    if (s.exactPages != null && n !== s.exactPages) bad(`page count ${n}, expected exactly ${s.exactPages}`);
    if (s.minPages && n < s.minPages) bad(`only ${n} pages, chunking should give at least ${s.minPages}`);
    if (s.sheets) {
      for (const sh of s.sheets) {
        if (sh.nonEmpty && sh.state !== 'hidden' && !has(allText, sh.name)) bad(`sheet name "${sh.name}" is not in the stored text/metadata`);
        if (sh.state === 'hidden' && !/hidden/i.test(allText)) bad('hidden sheet content is stored but nothing marks it hidden');
      }
      for (const es of s.emptySheets ?? []) if (hay.some((h) => h.includes(`\n${es}\n`) && h.trim().length < es.length + 5)) bad(`empty sheet "${es}" produced a page`);
    }
    if (s.headerRepeated && n >= 2) {
      const sheetCount = s.sheets?.length ?? 1;
      const withHdr = hay.filter((h) => s.headerRepeated.every((x) => has(h, x))).length;
      if (withHdr < n - (sheetCount - 1)) bad(`header not repeated on every chunk: ${withHdr}/${n} pages carry ${s.headerRepeated.join(' + ')}`);
    }
    // for 'either' files that were read: read questions
    if (exp.status === 'either') for (const [, expect] of exp.readQuestions ?? []) if (!has(allText, expect)) bad(`read but lost the legitimate text "${expect}"`);
    // recall
    for (const k of exp.keys) { st.keys++; if (has(allText, k)) st.keysHit++; else if (VERBOSE) console.log(`  missing key in ${name}: ${JSON.stringify(k).slice(0, 80)}`); }
    // questions
    const loc = new Map(pages.map((p, i) => [p.page_no, hay[i]]));
    for (const Q of exp.questions) {
      if (Q.kind === 'aggregate') {
        st.aggTotal++;
        const miss = Q.allOf.filter((id) => !has(allText, id));
        if (miss.length === 0) st.aggOk++; else bad(`aggregate "${Q.question}": ${miss.length}/${Q.allOf.length} sampled matching rows missing from stored text (e.g. ${miss[0]})`);
        continue;
      }
      st.qTotal++;
      let rows = [];
      try { rows = await RS.withTenant(ctxA, (db) => db.searchPassages(PROBE_ID && Q.same[0] ? Q.same[0] : Q.question, 5, Q.global ? {} : { documentIds: [created.documentId] })); } catch (e) { bad(`search threw: ${e.message}`); continue; }
      const textOf = (r) => loc.get(r.page_no) ?? '';
      const answersIn = (t) => Q.answers.every((a) => has(t, a)) && Q.same.every((x) => has(t, x));
      const topK = rows.some((r) => r.document_id === created.documentId && answersIn(textOf(r)));
      const top = rows[0];
      let why = null;
      if (!top) why = 'no result';
      else {
        const t = textOf(top);
        if (!Q.answers.every((a) => has(t, a))) why = `top page ${top.page_no} lacks answer ${JSON.stringify(Q.answers.find((a) => !has(t, a)))}`;
        else if (!Q.same.every((x) => has(t, x))) why = `top page ${top.page_no} lacks co-located "${Q.same.find((x) => !has(t, x))}"`;
        else if (Q.mustNot.find((m) => t.includes(m))) why = `top page contains forbidden "${Q.mustNot.find((m) => t.includes(m))}"`;
        else if (Q.markedHidden && !/hidden/i.test(t)) why = 'hidden-sheet answer not marked hidden';
        else if (Q.where.sheet && exp.type === 'xlsx' && !has(t, Q.where.sheet)) why = `top page does not name sheet "${Q.where.sheet}"`;
        else if (Q.where.page != null && (exp.structure?.docx || ['txt', 'md', 'json', 'pdf'].includes(exp.type))) {
          const tol = Q.pageTolerance ?? 1;
          if (Math.abs(top.page_no - Q.where.page) > tol) why = `cited page ${top.page_no}, expected ${Q.where.page} +-${tol}`;
        }
      }
      if (why && process.argv.includes('--diag-answer')) {
        const wide = await RS.withTenant(ctxA, (db) => db.searchPassages(Q.question, 12, { documentIds: [created.documentId] }));
        const onPages = pages.filter((_, i) => Q.answers.every((a) => has(hay[i], a)) && Q.same.every((x) => has(hay[i], x))).map((p) => p.page_no);
        console.log(`  diag-answer "${Q.question.slice(0, 50)}": answer on stored pages [${onPages}]; top-5 [${rows.map((r) => r.page_no)}]; top-12 [${wide.map((r) => r.page_no)}]`);
      }
      if (why && process.argv.includes('--diag') && Q.same[0]) {
        const d = await lite.query(`select page_no, tsv is null as nulltsv, tsv @@ plainto_tsquery('english', $2) as plain, position(lower($2) in lower(text)) > 0 as inText from document_pages where document_id=$1 and position(lower($2) in lower(text)) > 0`, [created.documentId, Q.same[0]]);
        console.log(`  diag ${Q.same[0]}: pages containing it: ${JSON.stringify(d.rows)}; search returned pages ${rows.map((r) => r.page_no).join(',')}`);
      }
      if (topK) st.qTopK++;
      const kl = knownHit(name, Q.question);
      if (kl) { klSeen.add(kl); if (!why) console.log(`NOTICE  ${name}: listed known limit now PASSES, remove it from known-limits.json: "${Q.question.slice(0, 60)}"`); }
      if (why && kl) { knownLimitCount++; console.log(`KNOWN LIMIT  ${name}: "${Q.question.slice(0, 70)}" -> ${why} [${kl.date}] ${kl.reason.slice(0, 120)}`); }
      else if (!why) st.qTop1++; else { okStatus = false; fail(name, `Q "${Q.question.slice(0, 70)}" -> ${why}${topK ? ' (but found in top 5)' : ' (NOT in top 5)'}`); }
    }
    ingested.push({ name, docId: created.documentId, firstQ: exp.questions.find((x) => x.kind !== 'aggregate'), pages: n });
  }
  if (okStatus) st.statusOk++;
  perFile.push({ name, type: exp.type, ok: okStatus, ms: Date.now() - tf, pages: pages.length });
  if (VERBOSE) console.log(`  ${name}: ${pages.length} pages in ${Date.now() - tf} ms`);
}

/* ---------------------------------------------------------------- (e) company isolation */
let iso = { checked: 0, leaks: 0 };
if (!ONLY || ingested.length) {
  const ids = ingested.map((x) => x.docId);
  for (const x of ingested) {
    if (!x.firstQ) continue;
    iso.checked++;
    const unscoped = await RS.withTenant(ctxB, (db) => db.searchPassages(x.firstQ.question, 10, {}));
    const scoped = ids.length ? await RS.withTenant(ctxB, (db) => db.searchPassages(x.firstQ.question, 10, { documentIds: [x.docId] })) : [];
    if (unscoped.length || scoped.length) { iso.leaks++; fail(x.name, `tenant B search returned ${unscoped.length + scoped.length} pages of tenant A`); }
  }
  const docsB = await RS.withTenant(ctxB, (db) => db.getDocument?.(ingested[0]?.docId));
  if (docsB) { iso.leaks++; fail('(isolation)', 'tenant B can read tenant A document row'); }
}

/* ---------------------------------------------------------------- (f) report */
globalThis.fetch = realFetch;
console.log('\nPER-TYPE RESULTS');
console.log('type    files  status-ok  recall(keys)        questions top-1 (right page+answer)  top-5     aggregates');
const rowsOut = Object.entries(typeStats).sort();
const tot = { files: 0, statusOk: 0, keys: 0, keysHit: 0, qTotal: 0, qTop1: 0, qTopK: 0, aggTotal: 0, aggOk: 0 };
for (const [t, s] of rowsOut) {
  for (const k of Object.keys(tot)) tot[k] += s[k];
  console.log(`${t.padEnd(7)} ${String(s.files).padStart(5)}  ${(s.statusOk + '/' + s.files).padStart(9)}  ${pct(s.keysHit, s.keys).padStart(7)} (${s.keysHit}/${s.keys})`.padEnd(54) + `${(s.qTop1 + '/' + s.qTotal).padStart(9)} ${pct(s.qTop1, s.qTotal).padStart(7)}      ${pct(s.qTopK, s.qTotal).padStart(7)}   ${s.aggOk}/${s.aggTotal}`);
}
console.log(`${'ALL'.padEnd(7)} ${String(tot.files).padStart(5)}  ${(tot.statusOk + '/' + tot.files).padStart(9)}  ${pct(tot.keysHit, tot.keys).padStart(7)} (${tot.keysHit}/${tot.keys})`.padEnd(54) + `${(tot.qTop1 + '/' + tot.qTotal).padStart(9)} ${pct(tot.qTop1, tot.qTotal).padStart(7)}      ${pct(tot.qTopK, tot.qTotal).padStart(7)}   ${tot.aggOk}/${tot.aggTotal}`);
console.log(`known limits (listed, not counted as pass): ${knownLimitCount}`);
console.log(`isolation: ${iso.checked} cross-tenant searches, ${iso.leaks} leaks; outbound non-R2 requests: ${outbound.length}; model calls: ${modelCalls}`);
console.log(`elapsed ${((Date.now() - t0) / 1000).toFixed(0)} s; slowest: ${perFile.sort((a, b) => (b.ms ?? 0) - (a.ms ?? 0)).slice(0, 3).map((p) => `${p.name} ${p.ms}ms`).join(', ')}`);
if (outbound.length) { failures.push(`outbound requests: ${outbound.join(', ')}`); }
if (iso.leaks) failures.push('tenant isolation leak');
console.log(failures.length ? `\nFAILED: ${failures.length} problem(s)` : '\nALL OFFICE-FILE CHECKS PASSED');
process.exit(failures.length ? 1 : 0);
